CREATE OR REPLACE FUNCTION "public"."check_uuid_consistency"() RETURNS TABLE("table_name" "text", "total_records" bigint, "consistent_uuids" bigint, "inconsistent_uuids" bigint, "consistency_percentage" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT * FROM uuid_consistency_check;
END;
$$;


ALTER FUNCTION "public"."check_uuid_consistency"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_company_uuid"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Only set UUID if it's not already provided
    IF NEW.id IS NULL THEN
        NEW.id := landbrugsdata_company_uuid(NEW.cvr_number);
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_company_uuid"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_company_uuid_by_cvr"("cvr_text" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    company_uuid UUID;
BEGIN
    -- Look up company UUID by CVR number
    SELECT id INTO company_uuid
    FROM companies
    WHERE cvr_number = cvr_text;

    -- If not found, this indicates the CVR enrichment pipeline hasn't processed this CVR yet
    IF company_uuid IS NULL THEN
        RAISE EXCEPTION 'CVR % not found in companies table. Run CVR enrichment pipeline first.', cvr_text;
    END IF;

    RETURN company_uuid;
END;
$$;


ALTER FUNCTION "public"."get_company_uuid_by_cvr"("cvr_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_company_uuid_by_cvr"("cvr_text" "text") IS 'Lookup company UUID by CVR number. This function ensures referential integrity by requiring that companies exist in the companies table (populated by CVR enrichment pipeline) before other data can reference them.';



CREATE OR REPLACE FUNCTION "public"."get_company_uuids_by_cvrs"("cvr_array" "text"[]) RETURNS TABLE("cvr_number" "text", "company_uuid" "uuid")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        unnest(cvr_array) as cvr_number,
        c.id as company_uuid
    FROM unnest(cvr_array) cvr
    LEFT JOIN companies c ON c.cvr_number = cvr;
END;
$$;


ALTER FUNCTION "public"."get_company_uuids_by_cvrs"("cvr_array" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_company_uuids_by_cvrs"("cvr_array" "text"[]) IS 'Bulk lookup of company UUIDs by CVR numbers. Returns a table with cvr_number and corresponding company_uuid. Returns NULL for company_uuid if CVR is not found.';



CREATE OR REPLACE FUNCTION "public"."landbrugsdata_chr_uuid"("chr_number" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
    IF chr_number IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN landbrugsdata_uuid5('chr', chr_number);
END;
$$;


ALTER FUNCTION "public"."landbrugsdata_chr_uuid"("chr_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."landbrugsdata_company_uuid"("cvr_number" bigint) RETURNS "uuid"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
    IF cvr_number IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN landbrugsdata_uuid5('company-cvr', cvr_number::TEXT);
END;
$$;


ALTER FUNCTION "public"."landbrugsdata_company_uuid"("cvr_number" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."landbrugsdata_company_uuid"("cvr_number" bigint) IS 'Generate deterministic UUID for companies based on CVR number. Always returns the same UUID for the same CVR.';



CREATE OR REPLACE FUNCTION "public"."landbrugsdata_field_uuid"("geometry_wkb" "bytea") RETURNS "uuid"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
    IF geometry_wkb IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN landbrugsdata_uuid5('field-geometry', encode(geometry_wkb, 'hex'));
END;
$$;


ALTER FUNCTION "public"."landbrugsdata_field_uuid"("geometry_wkb" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."landbrugsdata_pnumber_uuid"("p_number" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
    IF p_number IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN landbrugsdata_uuid5('pnumber', p_number);
END;
$$;


ALTER FUNCTION "public"."landbrugsdata_pnumber_uuid"("p_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."landbrugsdata_uuid5"("entity_type" "text", "identifier" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
    RETURN CONCAT(
        SUBSTR(md5(CONCAT('', entity_type, '-', identifier)), 1, 8), '-',
        SUBSTR(md5(CONCAT('', entity_type, '-', identifier)), 9, 4), '-',
        '5', SUBSTR(md5(CONCAT('', entity_type, '-', identifier)), 13, 3), '-',
        CONCAT('8', SUBSTR(md5(CONCAT('', entity_type, '-', identifier)), 16, 3)), '-',
        SUBSTR(md5(CONCAT('', entity_type, '-', identifier)), 19, 12)
    )::UUID;
END;
$$;


ALTER FUNCTION "public"."landbrugsdata_uuid5"("entity_type" "text", "identifier" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."landbrugsdata_uuid5"("entity_type" "text", "identifier" "text") IS 'Core deterministic UUID5 generation function using MD5 hash. Used by all entity-specific UUID functions.';


