CREATE MATERIALIZED VIEW "public"."site_yearly_summary" AS
 WITH "antibiotic_summary" AS (
         SELECT "antibiotic_usage"."chr_number",
            "antibiotic_usage"."year",
            "antibiotic_usage"."cvr_number",
            "sum"("antibiotic_usage"."animal_days") AS "total_animal_days",
            "sum"("antibiotic_usage"."animal_doses") AS "total_animal_doses",
            "avg"("antibiotic_usage"."add_per_100_dyr_per_dag") AS "avg_add_per_100_animals_per_day",
            "count"(*) AS "antibiotic_records"
           FROM "public"."antibiotic_usage"
          WHERE (("antibiotic_usage"."chr_number" IS NOT NULL) AND ("antibiotic_usage"."year" IS NOT NULL))
          GROUP BY "antibiotic_usage"."chr_number", "antibiotic_usage"."year", "antibiotic_usage"."cvr_number"
        ), "herd_capacity" AS (
         SELECT "herd_sizes"."chr_number",
            "sum"("herd_sizes"."count") AS "total_capacity",
            "count"(DISTINCT "herd_sizes"."species_code") AS "species_diversity",
            "max"("herd_sizes"."size_update_date") AS "latest_update_date"
           FROM "public"."herd_sizes"
          WHERE ("herd_sizes"."chr_number" IS NOT NULL)
          GROUP BY "herd_sizes"."chr_number"
        ), "all_chr_years" AS (
         SELECT DISTINCT "antibiotic_summary"."chr_number",
            "antibiotic_summary"."year"
           FROM "antibiotic_summary"
        UNION
         SELECT DISTINCT "herd_sizes"."chr_number",
            2025 AS "year"
           FROM "public"."herd_sizes"
          WHERE (NOT ("herd_sizes"."chr_number" IN ( SELECT DISTINCT "antibiotic_summary"."chr_number"
                   FROM "antibiotic_summary")))
        ), "site_info" AS (
         SELECT "production_sites"."chr",
            "production_sites"."company_id"
           FROM "public"."production_sites"
        )
 SELECT "gen_random_uuid"() AS "id",
    "acy"."chr_number" AS "chr",
    "acy"."year",
    COALESCE("ab"."cvr_number", ("si"."company_id")::"text") AS "owner_cvr",
    COALESCE("hc"."total_capacity", (0)::bigint) AS "capacity",
    NULL::"text" AS "current_disease_status",
        CASE
            WHEN ("ab"."total_animal_days" > (0)::numeric) THEN ("ab"."total_animal_days" / 365.0)
            ELSE (COALESCE("hc"."total_capacity", (0)::bigint))::numeric
        END AS "production_equiv",
    COALESCE("ab"."total_animal_doses", (0)::numeric) AS "antibiotics_ddd",
    0 AS "transport_count",
    "now"() AS "created_at",
    "now"() AS "updated_at"
   FROM ((("all_chr_years" "acy"
     LEFT JOIN "antibiotic_summary" "ab" ON ((("acy"."chr_number" = "ab"."chr_number") AND ("acy"."year" = "ab"."year"))))
     LEFT JOIN "herd_capacity" "hc" ON (("acy"."chr_number" = "hc"."chr_number")))
     LEFT JOIN "site_info" "si" ON (("acy"."chr_number" = "si"."chr")))
  WHERE (("acy"."chr_number" IS NOT NULL) AND ("acy"."year" IS NOT NULL) AND ((COALESCE("ab"."antibiotic_records", (0)::bigint) > 0) OR (COALESCE("hc"."total_capacity", (0)::bigint) >= 0)))
  WITH NO DATA;


ALTER TABLE "public"."site_yearly_summary" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."animal_welfare_summary" AS
 WITH "yearly_aw_totals" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            "sys"."year",
            "count"(DISTINCT "sys"."chr") AS "site_count",
            "sum"("sys"."production_equiv") AS "total_animal_equivalents",
            "sum"("sys"."antibiotics_ddd") AS "total_ddd_usage",
            "sum"("sys"."transport_count") AS "total_animals_transported"
           FROM (("public"."companies" "c"
             JOIN "public"."production_sites" "ps" ON (("c"."id" = "ps"."company_id")))
             JOIN "public"."site_yearly_summary" "sys" ON (("ps"."chr" = "sys"."chr")))
          GROUP BY "c"."id", "c"."municipality", "sys"."year"
        )
 SELECT "awt"."company_id",
    "awt"."municipality",
    "awt"."year",
    "awt"."site_count",
    "awt"."total_animal_equivalents",
    "awt"."total_ddd_usage",
    "awt"."total_animals_transported",
        CASE
            WHEN ("awt"."total_animal_equivalents" > (0)::numeric) THEN ("awt"."total_ddd_usage" / "awt"."total_animal_equivalents")
            ELSE (0)::numeric
        END AS "ddd_usage_rate",
    "row_number"() OVER (ORDER BY "awt"."total_animal_equivalents" DESC) AS "rank_dk_total_animal_equivalents",
    "row_number"() OVER (PARTITION BY "awt"."municipality" ORDER BY "awt"."total_animal_equivalents" DESC) AS "rank_municipality_total_animal_equivalents",
    "row_number"() OVER (ORDER BY "awt"."total_ddd_usage" DESC) AS "rank_dk_total_ddd_usage",
    "row_number"() OVER (PARTITION BY "awt"."municipality" ORDER BY "awt"."total_ddd_usage" DESC) AS "rank_municipality_total_ddd_usage",
    "row_number"() OVER (ORDER BY "awt"."total_animals_transported" DESC) AS "rank_dk_total_animals_transported",
    "row_number"() OVER (PARTITION BY "awt"."municipality" ORDER BY "awt"."total_animals_transported" DESC) AS "rank_municipality_total_animals_transported",
    "now"() AS "created_at",
    "now"() AS "updated_at"
   FROM "yearly_aw_totals" "awt"
  WITH NO DATA;


ALTER TABLE "public"."animal_welfare_summary" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."animal_welfare_summary" IS 'Animal welfare summary with ddd_usage_rate calculation. Fixed in migration 20250129000001.';



