CREATE OR REPLACE VIEW "public"."bnbo_environmental_status" AS
 WITH "yearly_bnbo_data" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            "fba"."year",
            COALESCE("sum"(
                CASE
                    WHEN ("fba"."bnbo_status" = ANY (ARRAY['Action Required'::"text", 'Gennemgået, indsats nødvendig'::"text", 'Ikke gennemgået (default værdi)'::"text"])) THEN "fba"."area_ha"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "action_required_hectares",
            COALESCE("sum"(
                CASE
                    WHEN ("fba"."bnbo_status" = ANY (ARRAY['Completed'::"text", 'Gennemgået, indsats ikke nødvendig'::"text", 'Indsats gennemført'::"text", 'Ingen erhvervsmæssig anvendelse af pesticider'::"text"])) THEN "fba"."area_ha"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "completed_hectares",
            COALESCE("sum"("fba"."water_covered_hectares"), (0)::numeric) AS "water_covered_hectares"
           FROM (("public"."companies" "c"
             LEFT JOIN "public"."field_boundaries" "fb" ON (("c"."id" = "fb"."company_id")))
             LEFT JOIN "public"."field_bnbo_areas" "fba" ON (("fb"."field_uuid" = "fba"."field_uuid")))
          WHERE ("fba"."year" IS NOT NULL)
          GROUP BY "c"."id", "c"."municipality", "fba"."year"
        )
 SELECT "yearly_bnbo_data"."company_id",
    "yearly_bnbo_data"."municipality",
    "yearly_bnbo_data"."year",
    "yearly_bnbo_data"."action_required_hectares",
    "yearly_bnbo_data"."completed_hectares",
    "yearly_bnbo_data"."water_covered_hectares",
        CASE
            WHEN (("yearly_bnbo_data"."action_required_hectares" + "yearly_bnbo_data"."completed_hectares") > (0)::numeric) THEN "round"((("yearly_bnbo_data"."completed_hectares" * 100.0) / ("yearly_bnbo_data"."action_required_hectares" + "yearly_bnbo_data"."completed_hectares")), 2)
            ELSE 100.0
        END AS "compliance_rate"
   FROM "yearly_bnbo_data"
  WHERE ("yearly_bnbo_data"."year" >= 2020);


ALTER TABLE "public"."bnbo_environmental_status" OWNER TO "postgres";


COMMENT ON VIEW "public"."bnbo_environmental_status" IS 'Time series view of BNBO environmental status showing action required, completed, and miljø- og klimaprojekt covered areas';



