CREATE MATERIALIZED VIEW "public"."bnbo_summary" AS
 WITH "yearly_status_totals" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            "fba"."year",
            "fba"."bnbo_status" AS "status",
            "sum"("fba"."area_ha") AS "area_ha"
           FROM ((("public"."companies" "c"
             JOIN "public"."field_yearly_data" "fyd" ON (("c"."cvr_number" = "fyd"."cvr_number")))
             JOIN "public"."field_boundaries" "fb" ON (("fyd"."field_uuid" = "fb"."field_uuid")))
             JOIN "public"."field_bnbo_areas" "fba" ON (("fb"."field_uuid" = "fba"."field_uuid")))
          WHERE ("fba"."bnbo_status" IS NOT NULL)
          GROUP BY "c"."id", "c"."municipality", "fba"."year", "fba"."bnbo_status"
        )
 SELECT "yst"."company_id",
    "yst"."municipality",
    "yst"."year",
    "yst"."status",
    "yst"."area_ha",
        CASE
            WHEN ("yst"."status" = 'not_dealt_with'::"text") THEN "rank"() OVER (PARTITION BY "yst"."year", "yst"."status" ORDER BY "yst"."area_ha" DESC NULLS LAST)
            ELSE NULL::bigint
        END AS "rank_dk_area_not_dealt_with",
        CASE
            WHEN ("yst"."status" = 'not_dealt_with'::"text") THEN "rank"() OVER (PARTITION BY "yst"."year", "yst"."municipality", "yst"."status" ORDER BY "yst"."area_ha" DESC NULLS LAST)
            ELSE NULL::bigint
        END AS "rank_municipality_area_not_dealt_with"
   FROM "yearly_status_totals" "yst"
  WITH NO DATA;


