CREATE MATERIALIZED VIEW "public"."carbon_summary" AS
 WITH "yearly_carbon_totals" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            "cef"."year",
            "sum"("cef"."co2e_tonnes") AS "total_co2e_tonnes"
           FROM ("public"."companies" "c"
             JOIN "public"."carbon_emission_factors" "cef" ON (("c"."id" = "cef"."company_id")))
          GROUP BY "c"."id", "c"."municipality", "cef"."year"
        )
 SELECT "yct"."company_id",
    "yct"."municipality",
    "yct"."year",
    "yct"."total_co2e_tonnes",
    "rank"() OVER (PARTITION BY "yct"."year" ORDER BY "yct"."total_co2e_tonnes" DESC NULLS LAST) AS "rank_dk_total_co2e_tonnes",
    "rank"() OVER (PARTITION BY "yct"."year", "yct"."municipality" ORDER BY "yct"."total_co2e_tonnes" DESC NULLS LAST) AS "rank_municipality_total_co2e_tonnes"
   FROM "yearly_carbon_totals" "yct"
  WITH NO DATA;


