CREATE MATERIALIZED VIEW "public"."company_pesticide_summary" AS
 SELECT "c"."id" AS "company_id",
    "c"."cvr_number",
    "c"."company_name",
    COALESCE("cpa"."field_municipality", "cpa"."municipality", 'Unknown'::"text") AS "municipality",
    "cpa"."application_year",
    "sum"((COALESCE("cpa"."total_burden_score", (0)::numeric) * COALESCE("cpa"."dosage_quantity", (0)::numeric))) AS "total_belastning",
    "sum"(
        CASE
            WHEN "cpa"."contains_pfas" THEN (COALESCE("cpa"."total_burden_score", (0)::numeric) * COALESCE("cpa"."dosage_quantity", (0)::numeric))
            ELSE (0)::numeric
        END) AS "pfas_belastning",
    "sum"(
        CASE
            WHEN "cpa"."contains_diquat" THEN (COALESCE("cpa"."total_burden_score", (0)::numeric) * COALESCE("cpa"."dosage_quantity", (0)::numeric))
            ELSE (0)::numeric
        END) AS "diquat_belastning",
    "sum"(
        CASE
            WHEN "cpa"."contains_glyphosate" THEN (COALESCE("cpa"."total_burden_score", (0)::numeric) * COALESCE("cpa"."dosage_quantity", (0)::numeric))
            ELSE (0)::numeric
        END) AS "glyphosate_belastning",
    "count"("cpa"."id") AS "total_applications",
    "count"(DISTINCT "cpa"."registration_number") AS "unique_products",
    "sum"(COALESCE("cpa"."treated_area_ha", (0)::numeric)) AS "total_treated_area_ha",
    "avg"(COALESCE("cpa"."total_burden_score", (0)::numeric)) AS "avg_burden_per_application",
    "count"(
        CASE
            WHEN "cpa"."contains_pfas" THEN 1
            ELSE NULL::integer
        END) AS "pfas_applications",
    "count"(
        CASE
            WHEN "cpa"."contains_diquat" THEN 1
            ELSE NULL::integer
        END) AS "diquat_applications",
    "count"(
        CASE
            WHEN "cpa"."contains_glyphosate" THEN 1
            ELSE NULL::integer
        END) AS "glyphosate_applications"
   FROM ("public"."companies" "c"
     JOIN "public"."company_pesticide_applications" "cpa" ON (("c"."id" = "cpa"."company_id")))
  GROUP BY "c"."id", "c"."cvr_number", "c"."company_name", COALESCE("cpa"."field_municipality", "cpa"."municipality", 'Unknown'::"text"), "cpa"."application_year"
  WITH NO DATA;


