CREATE MATERIALIZED VIEW "public"."environment_summary" AS
 WITH "yearly_env_totals" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            "fyd"."year",
            "sum"((COALESCE("pa"."total_burden_score", 1.0) * COALESCE("pa"."treated_area_ha", (0)::numeric))) AS "total_pesticide_load_index",
            "sum"("fyd"."area_ha") AS "total_area_ha",
            "sum"(COALESCE("fyd"."n_leached_kg", (0)::numeric)) AS "total_n_leached_kg",
            (0)::numeric AS "total_fertiliser_kg"
           FROM (("public"."companies" "c"
             JOIN "public"."field_yearly_data" "fyd" ON ((("c"."cvr_number")::"text" = ("fyd"."cvr_number")::"text")))
             LEFT JOIN "public"."pesticide_applications" "pa" ON ((("fyd"."field_uuid" = "pa"."field_uuid") AND ("fyd"."year" = "pa"."year"))))
          WHERE ("fyd"."year" IS NOT NULL)
          GROUP BY "c"."id", "c"."municipality", "fyd"."year"
        )
 SELECT "eet"."company_id",
    "eet"."municipality",
    "eet"."year",
    "eet"."total_n_leached_kg",
    "eet"."total_pesticide_load_index",
    "eet"."total_fertiliser_kg",
    "eet"."total_area_ha",
        CASE
            WHEN ("eet"."total_area_ha" > (0)::numeric) THEN ("eet"."total_n_leached_kg" / "eet"."total_area_ha")
            ELSE (0)::numeric
        END AS "n_leached_kg_per_ha",
        CASE
            WHEN ("eet"."total_area_ha" > (0)::numeric) THEN ("eet"."total_pesticide_load_index" / "eet"."total_area_ha")
            ELSE (0)::numeric
        END AS "pesticide_load_index_per_ha",
    "row_number"() OVER (PARTITION BY "eet"."year" ORDER BY "eet"."total_pesticide_load_index" DESC) AS "rank_dk_total_pesticide_load",
    "row_number"() OVER (PARTITION BY "eet"."year", "eet"."municipality" ORDER BY "eet"."total_pesticide_load_index" DESC) AS "rank_municipality_total_pesticide_load",
    "row_number"() OVER (PARTITION BY "eet"."year" ORDER BY
        CASE
            WHEN ("eet"."total_area_ha" > (0)::numeric) THEN ("eet"."total_pesticide_load_index" / "eet"."total_area_ha")
            ELSE (0)::numeric
        END DESC) AS "rank_dk_pesticide_load_per_ha",
    "row_number"() OVER (PARTITION BY "eet"."year", "eet"."municipality" ORDER BY
        CASE
            WHEN ("eet"."total_area_ha" > (0)::numeric) THEN ("eet"."total_pesticide_load_index" / "eet"."total_area_ha")
            ELSE (0)::numeric
        END DESC) AS "rank_municipality_pesticide_load_per_ha",
    "now"() AS "created_at",
    "now"() AS "updated_at"
   FROM "yearly_env_totals" "eet"
  WHERE ("eet"."total_area_ha" > (0)::numeric)
  WITH NO DATA;


ALTER TABLE "public"."environment_summary" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."environment_summary" IS 'Environmental summary using field_yearly_data for proper year-matched area calculations. Both pesticide load and areas are from the same year. Fixed in migration 20250829205500.';



CREATE MATERIALIZED VIEW "public"."environment_summary_optimized" AS
 WITH "yearly_env_totals" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            "fyd"."year",
            "sum"((COALESCE("pa"."total_burden_score", 1.0) * COALESCE("pa"."treated_area_ha", (0)::numeric))) AS "total_pesticide_load_index",
            "sum"("fyd"."area_ha") AS "total_area_ha",
            "sum"(COALESCE("fyd"."n_leached_kg", (0)::numeric)) AS "total_n_leached_kg",
            (0)::numeric AS "total_fertiliser_kg"
           FROM (("public"."companies" "c"
             JOIN "public"."field_yearly_data" "fyd" ON ((("c"."cvr_number")::"text" = ("fyd"."cvr_number")::"text")))
             LEFT JOIN "public"."pesticide_applications" "pa" ON ((("fyd"."field_uuid" = "pa"."field_uuid") AND ("fyd"."year" = "pa"."year"))))
          WHERE ((("fyd"."year")::numeric >= (EXTRACT(year FROM CURRENT_DATE) - (5)::numeric)) AND ("fyd"."year" IS NOT NULL) AND ("fyd"."area_ha" > (0)::numeric) AND ("c"."municipality" IS NOT NULL))
          GROUP BY "c"."id", "c"."municipality", "fyd"."year"
        )
 SELECT "eet"."company_id",
    "eet"."municipality",
    "eet"."year",
    "eet"."total_n_leached_kg",
    "eet"."total_pesticide_load_index",
    "eet"."total_fertiliser_kg",
    "eet"."total_area_ha",
        CASE
            WHEN ("eet"."total_area_ha" > (0)::numeric) THEN ("eet"."total_n_leached_kg" / "eet"."total_area_ha")
            ELSE (0)::numeric
        END AS "n_leached_kg_per_ha",
        CASE
            WHEN ("eet"."total_area_ha" > (0)::numeric) THEN ("eet"."total_pesticide_load_index" / "eet"."total_area_ha")
            ELSE (0)::numeric
        END AS "pesticide_load_index_per_ha",
    "rank"() OVER (PARTITION BY "eet"."year" ORDER BY "eet"."total_pesticide_load_index" DESC) AS "rank_dk_total_pesticide_load",
    "rank"() OVER (PARTITION BY "eet"."year", "eet"."municipality" ORDER BY "eet"."total_pesticide_load_index" DESC) AS "rank_municipality_total_pesticide_load",
    "rank"() OVER (PARTITION BY "eet"."year" ORDER BY
        CASE
            WHEN ("eet"."total_area_ha" > (0)::numeric) THEN ("eet"."total_pesticide_load_index" / "eet"."total_area_ha")
            ELSE (0)::numeric
        END DESC) AS "rank_dk_pesticide_load_per_ha",
    "rank"() OVER (PARTITION BY "eet"."year", "eet"."municipality" ORDER BY
        CASE
            WHEN ("eet"."total_area_ha" > (0)::numeric) THEN ("eet"."total_pesticide_load_index" / "eet"."total_area_ha")
            ELSE (0)::numeric
        END DESC) AS "rank_municipality_pesticide_load_per_ha",
    "now"() AS "created_at",
    "now"() AS "updated_at"
   FROM "yearly_env_totals" "eet"
  WHERE ("eet"."total_area_ha" > (0)::numeric)
  WITH NO DATA;


ALTER TABLE "public"."environment_summary_optimized" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."environment_summary_optimized" IS 'Optimized version with 5-year filtering and improved joins - estimated 80% faster refresh. Refresh manually: REFRESH MATERIALIZED VIEW environment_summary_optimized;';



