CREATE OR REPLACE VIEW "public"."environmental_action_status" AS
 WITH "current_year_data" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            EXTRACT(year FROM CURRENT_DATE) AS "year",
            'BNBO'::"text" AS "area_type",
                CASE
                    WHEN ("fba"."bnbo_status" = ANY (ARRAY['Action Required'::"text", 'Gennemgået, indsats nødvendig'::"text", 'Ikke gennemgået (default værdi)'::"text"])) THEN 'Kræver Handling'::"text"
                    WHEN ("fba"."bnbo_status" = ANY (ARRAY['Completed'::"text", 'Gennemgået, indsats ikke nødvendig'::"text", 'Indsats gennemført'::"text", 'Ingen erhvervsmæssig anvendelse af pesticider'::"text"])) THEN 'Gennemført'::"text"
                    WHEN ("fba"."water_covered_hectares" > (0)::numeric) THEN 'Areal til Klima- eller Miljøprojekter'::"text"
                    ELSE 'Ukendt'::"text"
                END AS "action_status",
            COALESCE("sum"("fba"."area_ha"), (0)::numeric) AS "area_hectares"
           FROM (("public"."companies" "c"
             LEFT JOIN "public"."field_boundaries" "fb" ON (("c"."id" = "fb"."company_id")))
             LEFT JOIN "public"."field_bnbo_areas" "fba" ON (("fb"."field_uuid" = "fba"."field_uuid")))
          WHERE ((("fba"."year")::numeric = EXTRACT(year FROM CURRENT_DATE)) OR ("fba"."year" IS NULL))
          GROUP BY "c"."id", "c"."municipality", 'BNBO'::"text",
                CASE
                    WHEN ("fba"."bnbo_status" = ANY (ARRAY['Action Required'::"text", 'Gennemgået, indsats nødvendig'::"text", 'Ikke gennemgået (default værdi)'::"text"])) THEN 'Kræver Handling'::"text"
                    WHEN ("fba"."bnbo_status" = ANY (ARRAY['Completed'::"text", 'Gennemgået, indsats ikke nødvendig'::"text", 'Indsats gennemført'::"text", 'Ingen erhvervsmæssig anvendelse af pesticider'::"text"])) THEN 'Gennemført'::"text"
                    WHEN ("fba"."water_covered_hectares" > (0)::numeric) THEN 'Areal til Klima- eller Miljøprojekter'::"text"
                    ELSE 'Ukendt'::"text"
                END
        UNION ALL
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            EXTRACT(year FROM CURRENT_DATE) AS "year",
            'Lavbundsjorde'::"text" AS "area_type",
                CASE
                    WHEN (("fwa"."wetlands_status" = 'present'::"text") AND (("fwa"."water_covered_hectares" IS NULL) OR ("fwa"."water_covered_hectares" = (0)::numeric))) THEN 'Kræver Handling'::"text"
                    WHEN (("fwa"."wetlands_status" = 'present'::"text") AND ("fwa"."water_covered_hectares" > (0)::numeric)) THEN 'Gennemført'::"text"
                    WHEN ("fwa"."water_covered_hectares" > (0)::numeric) THEN 'Areal til Klima- eller Miljøprojekter'::"text"
                    ELSE 'Ukendt'::"text"
                END AS "action_status",
            COALESCE("sum"("fwa"."area_ha"), (0)::numeric) AS "area_hectares"
           FROM (("public"."companies" "c"
             LEFT JOIN "public"."field_boundaries" "fb" ON (("c"."id" = "fb"."company_id")))
             LEFT JOIN "public"."field_wetland_areas" "fwa" ON (("fb"."field_uuid" = "fwa"."field_uuid")))
          WHERE ((("fwa"."year")::numeric = EXTRACT(year FROM CURRENT_DATE)) OR ("fwa"."year" IS NULL))
          GROUP BY "c"."id", "c"."municipality", 'Lavbundsjorde'::"text",
                CASE
                    WHEN (("fwa"."wetlands_status" = 'present'::"text") AND (("fwa"."water_covered_hectares" IS NULL) OR ("fwa"."water_covered_hectares" = (0)::numeric))) THEN 'Kræver Handling'::"text"
                    WHEN (("fwa"."wetlands_status" = 'present'::"text") AND ("fwa"."water_covered_hectares" > (0)::numeric)) THEN 'Gennemført'::"text"
                    WHEN ("fwa"."water_covered_hectares" > (0)::numeric) THEN 'Areal til Klima- eller Miljøprojekter'::"text"
                    ELSE 'Ukendt'::"text"
                END
        )
 SELECT "current_year_data"."company_id",
    "current_year_data"."municipality",
    "current_year_data"."year",
    "current_year_data"."area_type",
    "current_year_data"."action_status",
    "current_year_data"."area_hectares"
   FROM "current_year_data"
  WHERE ("current_year_data"."area_hectares" > (0)::numeric);


ALTER TABLE "public"."environmental_action_status" OWNER TO "postgres";


COMMENT ON VIEW "public"."environmental_action_status" IS 'Current year environmental action status breakdown by area type and action status';



CREATE OR REPLACE VIEW "public"."environmental_compliance_summary" AS
 WITH "company_environmental_data" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            2025 AS "year",
            COALESCE("sum"(
                CASE
                    WHEN ("fba"."bnbo_status" = ANY (ARRAY['Action Required'::"text", 'Gennemgået, indsats nødvendig'::"text", 'Ikke gennemgået (default værdi)'::"text"])) THEN "fba"."area_ha"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "bnbo_problematic_hectares",
            COALESCE("sum"(
                CASE
                    WHEN ("fba"."bnbo_status" = ANY (ARRAY['Completed'::"text", 'Gennemgået, indsats ikke nødvendig'::"text", 'Indsats gennemført'::"text", 'Ingen erhvervsmæssig anvendelse af pesticider'::"text"])) THEN "fba"."area_ha"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "bnbo_dealt_with_hectares",
            COALESCE("sum"("fba"."water_covered_hectares"), (0)::numeric) AS "bnbo_water_covered_hectares",
            COALESCE("sum"(
                CASE
                    WHEN (("fwa"."wetlands_status" = 'present'::"text") AND (("fwa"."water_covered_hectares" IS NULL) OR ("fwa"."water_covered_hectares" = (0)::numeric))) THEN "fwa"."area_ha"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "wetlands_problematic_hectares",
            COALESCE("sum"(
                CASE
                    WHEN (("fwa"."wetlands_status" = 'present'::"text") AND ("fwa"."water_covered_hectares" > (0)::numeric)) THEN "fwa"."water_covered_hectares"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "wetlands_dealt_with_hectares",
            COALESCE("sum"(
                CASE
                    WHEN ("fwa"."wetlands_status" = 'present'::"text") THEN "fwa"."water_covered_hectares"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "wetlands_water_covered_hectares"
           FROM ((("public"."companies" "c"
             LEFT JOIN "public"."field_boundaries" "fb" ON (("c"."id" = "fb"."company_id")))
             LEFT JOIN "public"."field_bnbo_areas" "fba" ON ((("fb"."field_uuid" = "fba"."field_uuid") AND ("fba"."year" = 2025))))
             LEFT JOIN "public"."field_wetland_areas" "fwa" ON ((("fb"."field_uuid" = "fwa"."field_uuid") AND ("fwa"."year" = 2025))))
          GROUP BY "c"."id", "c"."municipality"
        )
 SELECT "company_environmental_data"."company_id",
    "company_environmental_data"."municipality",
    "company_environmental_data"."year",
    ("company_environmental_data"."bnbo_problematic_hectares" + "company_environmental_data"."wetlands_problematic_hectares") AS "total_problematic_hectares",
    ("company_environmental_data"."bnbo_dealt_with_hectares" + "company_environmental_data"."wetlands_dealt_with_hectares") AS "total_dealt_with_hectares",
    ("company_environmental_data"."bnbo_water_covered_hectares" + "company_environmental_data"."wetlands_water_covered_hectares") AS "total_water_covered_hectares",
        CASE
            WHEN (((("company_environmental_data"."bnbo_problematic_hectares" + "company_environmental_data"."wetlands_problematic_hectares") + "company_environmental_data"."bnbo_dealt_with_hectares") + "company_environmental_data"."wetlands_dealt_with_hectares") > (0)::numeric) THEN "round"(((("company_environmental_data"."bnbo_dealt_with_hectares" + "company_environmental_data"."wetlands_dealt_with_hectares") * 100.0) / ((("company_environmental_data"."bnbo_problematic_hectares" + "company_environmental_data"."wetlands_problematic_hectares") + "company_environmental_data"."bnbo_dealt_with_hectares") + "company_environmental_data"."wetlands_dealt_with_hectares")), 2)
            ELSE 100.0
        END AS "compliance_percentage",
        CASE
            WHEN (((("company_environmental_data"."bnbo_problematic_hectares" + "company_environmental_data"."wetlands_problematic_hectares") + "company_environmental_data"."bnbo_dealt_with_hectares") + "company_environmental_data"."wetlands_dealt_with_hectares") > (0)::numeric) THEN "round"(((("company_environmental_data"."bnbo_water_covered_hectares" + "company_environmental_data"."wetlands_water_covered_hectares") * 100.0) / ((("company_environmental_data"."bnbo_problematic_hectares" + "company_environmental_data"."wetlands_problematic_hectares") + "company_environmental_data"."bnbo_dealt_with_hectares") + "company_environmental_data"."wetlands_dealt_with_hectares")), 2)
            ELSE 0.0
        END AS "water_coverage_percentage",
    "company_environmental_data"."bnbo_problematic_hectares",
    "company_environmental_data"."bnbo_dealt_with_hectares",
    "company_environmental_data"."bnbo_water_covered_hectares",
    "company_environmental_data"."wetlands_problematic_hectares",
    "company_environmental_data"."wetlands_dealt_with_hectares",
    "company_environmental_data"."wetlands_water_covered_hectares"
   FROM "company_environmental_data"
  WHERE (((("company_environmental_data"."bnbo_problematic_hectares" + "company_environmental_data"."wetlands_problematic_hectares") + "company_environmental_data"."bnbo_dealt_with_hectares") + "company_environmental_data"."wetlands_dealt_with_hectares") > (0)::numeric);


ALTER TABLE "public"."environmental_compliance_summary" OWNER TO "postgres";


COMMENT ON VIEW "public"."environmental_compliance_summary" IS 'Environmental compliance summary with corrected column references for wetlands_status';



CREATE OR REPLACE VIEW "public"."environmental_compliance_ranking" AS
 SELECT "environmental_compliance_summary"."company_id",
    "environmental_compliance_summary"."municipality",
    "environmental_compliance_summary"."year",
    "environmental_compliance_summary"."total_problematic_hectares" AS "total_non_compliant_hectares",
        CASE
            WHEN ("environmental_compliance_summary"."total_problematic_hectares" > (100)::numeric) THEN 'High'::"text"
            WHEN ("environmental_compliance_summary"."total_problematic_hectares" > (10)::numeric) THEN 'Medium'::"text"
            ELSE 'Low'::"text"
        END AS "environmental_risk_score",
    "row_number"() OVER (ORDER BY "environmental_compliance_summary"."total_problematic_hectares" DESC) AS "rank_dk_compliance",
    "row_number"() OVER (PARTITION BY "environmental_compliance_summary"."municipality" ORDER BY "environmental_compliance_summary"."total_problematic_hectares" DESC) AS "rank_municipality_compliance",
    "row_number"() OVER (ORDER BY "environmental_compliance_summary"."total_water_covered_hectares" DESC) AS "rank_dk_water_coverage",
    "row_number"() OVER (PARTITION BY "environmental_compliance_summary"."municipality" ORDER BY "environmental_compliance_summary"."total_water_covered_hectares" DESC) AS "rank_municipality_water_coverage"
   FROM "public"."environmental_compliance_summary";


ALTER TABLE "public"."environmental_compliance_ranking" OWNER TO "postgres";


COMMENT ON VIEW "public"."environmental_compliance_ranking" IS 'Environmental compliance rankings based on compliance summary to prevent 500 errors';



CREATE OR REPLACE VIEW "public"."foreign_key_validation" AS
 SELECT 'field_yearly_data'::"text" AS "table_name",
    "count"(*) AS "total_records",
    "count"("f"."company_id") AS "with_company_id",
    ("count"(
        CASE
            WHEN ("f"."company_id" IS NOT NULL) THEN 1
            ELSE NULL::integer
        END) - "count"(
        CASE
            WHEN ("c"."id" IS NOT NULL) THEN 1
            ELSE NULL::integer
        END)) AS "orphaned_references"
   FROM ("public"."field_yearly_data" "f"
     LEFT JOIN "public"."companies" "c" ON (("f"."company_id" = "c"."id")))
UNION ALL
 SELECT 'pesticide_applications'::"text" AS "table_name",
    "count"(*) AS "total_records",
    "count"("p"."company_id") AS "with_company_id",
    ("count"(
        CASE
            WHEN ("p"."company_id" IS NOT NULL) THEN 1
            ELSE NULL::integer
        END) - "count"(
        CASE
            WHEN ("c"."id" IS NOT NULL) THEN 1
            ELSE NULL::integer
        END)) AS "orphaned_references"
   FROM ("public"."pesticide_applications" "p"
     LEFT JOIN "public"."companies" "c" ON (("p"."company_id" = "c"."id")))
UNION ALL
 SELECT 'production_sites'::"text" AS "table_name",
    "count"(*) AS "total_records",
    "count"("ps"."company_id") AS "with_company_id",
    ("count"(
        CASE
            WHEN ("ps"."company_id" IS NOT NULL) THEN 1
            ELSE NULL::integer
        END) - "count"(
        CASE
            WHEN ("c"."id" IS NOT NULL) THEN 1
            ELSE NULL::integer
        END)) AS "orphaned_references"
   FROM ("public"."production_sites" "ps"
     LEFT JOIN "public"."companies" "c" ON (("ps"."company_id" = "c"."id")));


ALTER TABLE "public"."foreign_key_validation" OWNER TO "postgres";


COMMENT ON VIEW "public"."foreign_key_validation" IS 'Validates foreign key integrity across all company-related tables. Orphaned references should be 0.';



