CREATE MATERIALIZED VIEW "public"."land_use_summary" AS
 WITH "latest_total_data" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            2025 AS "year",
            "sum"("fyd"."area_ha") AS "total_area_ha",
            "count"(DISTINCT "fyd"."field_uuid") AS "total_fields"
           FROM (("public"."companies" "c"
             JOIN "public"."field_boundaries" "fb" ON (("c"."id" = "fb"."company_id")))
             JOIN "public"."field_yearly_data" "fyd" ON (("fb"."field_uuid" = "fyd"."field_uuid")))
          WHERE (("c"."municipality" IS NOT NULL) AND ("fyd"."year" = 2025) AND ("fyd"."area_ha" > (0)::numeric))
          GROUP BY "c"."id", "c"."municipality"
        ), "latest_organic_data" AS (
         SELECT "c"."id" AS "company_id",
            "sum"(
                CASE
                    WHEN ("fyd"."is_organic" = true) THEN "fyd"."area_ha"
                    ELSE (0)::numeric
                END) AS "organic_area_ha"
           FROM (("public"."companies" "c"
             JOIN "public"."field_boundaries" "fb" ON (("c"."id" = "fb"."company_id")))
             JOIN "public"."field_yearly_data" "fyd" ON (("fb"."field_uuid" = "fyd"."field_uuid")))
          WHERE (("c"."municipality" IS NOT NULL) AND ("fyd"."year" = 2024) AND ("fyd"."area_ha" > (0)::numeric))
          GROUP BY "c"."id"
        ), "combined_data" AS (
         SELECT "ltd"."company_id",
            "ltd"."municipality",
            "ltd"."year",
            "ltd"."total_area_ha",
            COALESCE("lod"."organic_area_ha", (0)::numeric) AS "organic_area_ha",
            "ltd"."total_fields"
           FROM ("latest_total_data" "ltd"
             LEFT JOIN "latest_organic_data" "lod" ON (("ltd"."company_id" = "lod"."company_id")))
        )
 SELECT "combined_data"."company_id",
    "combined_data"."municipality",
    "combined_data"."year",
    "combined_data"."total_area_ha",
    "combined_data"."organic_area_ha",
    "combined_data"."total_fields",
    "rank"() OVER (ORDER BY "combined_data"."total_area_ha" DESC) AS "rank_dk_total_area",
    "rank"() OVER (ORDER BY "combined_data"."organic_area_ha" DESC) AS "rank_dk_organic_total_area",
    "rank"() OVER (PARTITION BY "combined_data"."municipality" ORDER BY "combined_data"."total_area_ha" DESC) AS "rank_municipality_total_area",
    "rank"() OVER (PARTITION BY "combined_data"."municipality" ORDER BY "combined_data"."organic_area_ha" DESC) AS "rank_municipality_organic_total_area",
        CASE
            WHEN ("combined_data"."total_area_ha" > (0)::numeric) THEN (("combined_data"."organic_area_ha" / "combined_data"."total_area_ha") * (100)::numeric)
            ELSE (0)::numeric
        END AS "organic_percentage"
   FROM "combined_data"
  WITH NO DATA;


ALTER TABLE "public"."land_use_summary" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."municipality_pesticide_summary" AS
 SELECT "company_pesticide_summary"."municipality",
    "company_pesticide_summary"."application_year",
    "count"(DISTINCT "company_pesticide_summary"."cvr_number") AS "company_count",
    "sum"("company_pesticide_summary"."total_belastning") AS "total_belastning",
    "sum"("company_pesticide_summary"."pfas_belastning") AS "pfas_belastning",
    "sum"("company_pesticide_summary"."diquat_belastning") AS "diquat_belastning",
    "sum"("company_pesticide_summary"."glyphosate_belastning") AS "glyphosate_belastning",
    "sum"("company_pesticide_summary"."total_applications") AS "total_applications",
    "sum"("company_pesticide_summary"."total_treated_area_ha") AS "total_treated_area_ha",
    "avg"("company_pesticide_summary"."avg_burden_per_application") AS "avg_municipal_burden",
    "rank"() OVER (PARTITION BY "company_pesticide_summary"."application_year" ORDER BY ("sum"("company_pesticide_summary"."total_belastning")) DESC) AS "burden_rank",
    "rank"() OVER (PARTITION BY "company_pesticide_summary"."application_year" ORDER BY ("sum"("company_pesticide_summary"."total_treated_area_ha")) DESC) AS "area_rank"
   FROM "public"."company_pesticide_summary"
  WHERE ("company_pesticide_summary"."municipality" <> 'Unknown'::"text")
  GROUP BY "company_pesticide_summary"."municipality", "company_pesticide_summary"."application_year"
  WITH NO DATA;


