CREATE OR REPLACE VIEW "public"."uuid_consistency_check" AS
 SELECT 'companies'::"text" AS "table_name",
    "count"(*) AS "total_records",
    "count"(
        CASE
            WHEN ("companies"."id" = "public"."landbrugsdata_company_uuid"("companies"."cvr_number")) THEN 1
            ELSE NULL::integer
        END) AS "consistent_uuids",
    "count"(
        CASE
            WHEN ("companies"."id" <> "public"."landbrugsdata_company_uuid"("companies"."cvr_number")) THEN 1
            ELSE NULL::integer
        END) AS "inconsistent_uuids",
    "round"(((("count"(
        CASE
            WHEN ("companies"."id" = "public"."landbrugsdata_company_uuid"("companies"."cvr_number")) THEN 1
            ELSE NULL::integer
        END))::numeric / ("count"(*))::numeric) * (100)::numeric), 2) AS "consistency_percentage"
   FROM "public"."companies";


