CREATE OR REPLACE VIEW "public"."water_coverage_effectiveness" AS
 WITH "yearly_coverage_data" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            "fba"."year",
            'BNBO Klima- eller Miljøprojekter'::"text" AS "coverage_type",
            COALESCE("sum"("fba"."water_covered_hectares"), (0)::numeric) AS "coverage_hectares"
           FROM (("public"."companies" "c"
             LEFT JOIN "public"."field_boundaries" "fb" ON (("c"."id" = "fb"."company_id")))
             LEFT JOIN "public"."field_bnbo_areas" "fba" ON (("fb"."field_uuid" = "fba"."field_uuid")))
          WHERE (("fba"."year" IS NOT NULL) AND ("fba"."water_covered_hectares" > (0)::numeric))
          GROUP BY "c"."id", "c"."municipality", "fba"."year", 'BNBO Klima- eller Miljøprojekter'::"text"
        UNION ALL
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            "fwa"."year",
            'Lavbundsjorde Klima- eller Miljøprojekter'::"text" AS "coverage_type",
            COALESCE("sum"("fwa"."water_covered_hectares"), (0)::numeric) AS "coverage_hectares"
           FROM (("public"."companies" "c"
             LEFT JOIN "public"."field_boundaries" "fb" ON (("c"."id" = "fb"."company_id")))
             LEFT JOIN "public"."field_wetland_areas" "fwa" ON (("fb"."field_uuid" = "fwa"."field_uuid")))
          WHERE (("fwa"."year" IS NOT NULL) AND ("fwa"."water_covered_hectares" > (0)::numeric))
          GROUP BY "c"."id", "c"."municipality", "fwa"."year", 'Lavbundsjorde Klima- eller Miljøprojekter'::"text"
        )
 SELECT "yearly_coverage_data"."company_id",
    "yearly_coverage_data"."municipality",
    "yearly_coverage_data"."year",
    "yearly_coverage_data"."coverage_type",
    "yearly_coverage_data"."coverage_hectares"
   FROM "yearly_coverage_data"
  WHERE (("yearly_coverage_data"."year" >= 2020) AND ("yearly_coverage_data"."coverage_hectares" > (0)::numeric));


ALTER TABLE "public"."water_coverage_effectiveness" OWNER TO "postgres";


COMMENT ON VIEW "public"."water_coverage_effectiveness" IS 'Time series view of miljø- og klimaprojekt coverage effectiveness for BNBO and lavbundsjorde';



CREATE MATERIALIZED VIEW "public"."wetlands_environmental_status" AS
 WITH "yearly_wetlands_data" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            "fwa"."year",
            COALESCE("sum"(
                CASE
                    WHEN (("fwa"."wetlands_status" = 'present'::"text") AND (("fwa"."water_covered_hectares" IS NULL) OR ("fwa"."water_covered_hectares" = (0)::numeric))) THEN "fwa"."area_ha"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "action_required_hectares",
            COALESCE("sum"(
                CASE
                    WHEN (("fwa"."wetlands_status" = 'present'::"text") AND ("fwa"."water_covered_hectares" > (0)::numeric)) THEN "fwa"."water_covered_hectares"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "completed_hectares",
            COALESCE("sum"("fwa"."water_covered_hectares"), (0)::numeric) AS "water_covered_hectares"
           FROM (("public"."companies" "c"
             LEFT JOIN "public"."field_boundaries" "fb" ON (("c"."id" = "fb"."company_id")))
             LEFT JOIN "public"."field_wetland_areas" "fwa" ON (("fb"."field_uuid" = "fwa"."field_uuid")))
          WHERE ("fwa"."year" IS NOT NULL)
          GROUP BY "c"."id", "c"."municipality", "fwa"."year"
        )
 SELECT "yearly_wetlands_data"."company_id",
    "yearly_wetlands_data"."municipality",
    "yearly_wetlands_data"."year",
    "yearly_wetlands_data"."action_required_hectares",
    "yearly_wetlands_data"."completed_hectares",
    "yearly_wetlands_data"."water_covered_hectares",
        CASE
            WHEN (("yearly_wetlands_data"."action_required_hectares" + "yearly_wetlands_data"."completed_hectares") > (0)::numeric) THEN "round"((("yearly_wetlands_data"."completed_hectares" * 100.0) / ("yearly_wetlands_data"."action_required_hectares" + "yearly_wetlands_data"."completed_hectares")), 2)
            ELSE 100.0
        END AS "protection_rate"
   FROM "yearly_wetlands_data"
  WHERE (("yearly_wetlands_data"."year" >= 2020) AND (("yearly_wetlands_data"."action_required_hectares" > (0)::numeric) OR ("yearly_wetlands_data"."completed_hectares" > (0)::numeric)))
  WITH NO DATA;


ALTER TABLE "public"."wetlands_environmental_status" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."wetlands_environmental_status" IS 'Materialized view for wetlands environmental status. Optimized for performance to prevent API timeouts. Water coverage = restored areas, no water coverage = action required areas. Refresh periodically with REFRESH MATERIALIZED VIEW.';



CREATE MATERIALIZED VIEW "public"."wetlands_summary" AS
 WITH "yearly_status_totals" AS (
         SELECT "c"."id" AS "company_id",
            "c"."municipality",
            "fwa"."year",
            "fwa"."wetlands_status" AS "status",
            "sum"("fwa"."area_ha") AS "area_ha"
           FROM (("public"."companies" "c"
             JOIN "public"."field_boundaries" "fb" ON (("c"."cvr_number" = "fb"."cvr_number")))
             JOIN "public"."field_wetland_areas" "fwa" ON (("fb"."field_uuid" = "fwa"."field_uuid")))
          WHERE ("fwa"."wetlands_status" IS NOT NULL)
          GROUP BY "c"."id", "c"."municipality", "fwa"."year", "fwa"."wetlands_status"
        )
 SELECT "yst"."company_id",
    "yst"."municipality",
    "yst"."year",
    "yst"."status",
    "yst"."area_ha",
        CASE
            WHEN ("yst"."status" = 'not_dealt_with'::"text") THEN "rank"() OVER (PARTITION BY "yst"."year", "yst"."status" ORDER BY "yst"."area_ha" DESC NULLS LAST)
            ELSE NULL::bigint
        END AS "rank_dk_area_not_dealt_with",
        CASE
            WHEN ("yst"."status" = 'not_dealt_with'::"text") THEN "rank"() OVER (PARTITION BY "yst"."year", "yst"."municipality", "yst"."status" ORDER BY "yst"."area_ha" DESC NULLS LAST)
            ELSE NULL::bigint
        END AS "rank_municipality_area_not_dealt_with"
   FROM "yearly_status_totals" "yst"
  WITH NO DATA;


ALTER TABLE "public"."wetlands_summary" OWNER TO "postgres";


