CREATE TABLE IF NOT EXISTS "public"."yearly_financials" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "company_uuid" "uuid" NOT NULL,
    "cvr_number" bigint NOT NULL,
