ALTER TABLE ONLY "public"."production_sites"
    ADD CONSTRAINT "production_sites_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "public"."companies"("id");



ALTER TABLE ONLY "public"."production_sites"
    ADD CONSTRAINT "production_sites_main_species_code_fkey" FOREIGN KEY ("main_species_code") REFERENCES "public"."species"("species_code");



ALTER TABLE ONLY "public"."subsidy_details"
    ADD CONSTRAINT "subsidy_details_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "public"."companies"("id");



ALTER TABLE ONLY "public"."vet_events"
    ADD CONSTRAINT "vet_events_chr_fkey" FOREIGN KEY ("chr") REFERENCES "public"."production_sites"("chr") ON DELETE CASCADE;



ALTER TABLE ONLY "public"."vet_events"
    ADD CONSTRAINT "vet_events_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "public"."companies"("id") ON DELETE CASCADE;



ALTER TABLE ONLY "public"."vet_events"
    ADD CONSTRAINT "vet_events_species_code_fkey" FOREIGN KEY ("species_code") REFERENCES "public"."species"("species_code");



ALTER TABLE ONLY "public"."visa_yearly_counts"
    ADD CONSTRAINT "visa_yearly_counts_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "public"."companies"("id");



ALTER TABLE ONLY "public"."worker_yearly_summary"
    ADD CONSTRAINT "worker_yearly_summary_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "public"."companies"("id");



ALTER TABLE ONLY "public"."yearly_financials"
    ADD CONSTRAINT "yearly_financials_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "public"."companies"("id");





